import{_ as e,o as s,c as i,a2 as a}from"./chunks/framework.CZo9GF0W.js";const k=JSON.parse('{"title":"Connections","description":"","frontmatter":{},"headers":[],"relativePath":"guide/connections.md","filePath":"guide/connections.md","lastUpdated":1789060268000}'),n={name:"guide/connections.md"};function o(r,t,d,h,l,p){return s(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h1><h2 id="where-a-profile-lives" tabindex="-1">Where a profile lives <a class="header-anchor" href="#where-a-profile-lives" aria-label="Permalink to &quot;Where a profile lives&quot;">​</a></h2><p>A connection profile has two halves: the description, which is ordinary JSON, and the secret, which is not.</p><table tabindex="0"><thead><tr><th>Part</th><th>Stored in</th><th>Safe to commit</th></tr></thead><tbody><tr><td>Personal profiles</td><td>VS Code global state</td><td>n/a — not a file you share</td></tr><tr><td>Shared profiles</td><td><code>.vscode/pitta.connections.json</code> in the workspace</td><td><strong>yes</strong></td></tr><tr><td>Every password, passphrase and key password</td><td>OS keychain, via <code>vscode.SecretStorage</code></td><td>never written to a file at all</td></tr></tbody></table><p>The shared file is validated against a published JSON Schema that <strong>rejects a literal string</strong> in any password field. A profile that contains a password is not accepted-with-a-warning; it is refused with an error naming the field. That is what makes the file safe to commit: not a convention, a schema.</p><p>Add <code>$schema</code> for completion and inline validation as you edit it:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://raw.githubusercontent.com/shresthadeepesh/pitta-db/main/packages/extension/schemas/pitta.connections.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;connections&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orders-staging&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;driver&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;postgres&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;environment&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;staging&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;connection&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;host&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;db.staging.internal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;database&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;app_ro&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;keychain&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;ssl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;verify-full&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;readOnly&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Everyone on the team gets the connection; everyone supplies their own credential.</p><h2 id="supplying-the-secret" tabindex="-1">Supplying the secret <a class="header-anchor" href="#supplying-the-secret" aria-label="Permalink to &quot;Supplying the secret&quot;">​</a></h2><p><code>password</code> is a <strong>reference</strong>, never a value. The kinds:</p><table tabindex="0"><thead><tr><th>Reference</th><th>What happens</th><th>Good for</th></tr></thead><tbody><tr><td><code>{ &quot;kind&quot;: &quot;keychain&quot; }</code></td><td>Read from the OS keychain at connect time. Pitta prompts once and stores it.</td><td>The default.</td></tr><tr><td><code>{ &quot;kind&quot;: &quot;env&quot;, &quot;name&quot;: &quot;PGPASSWORD&quot; }</code></td><td>Read from the environment of the extension host at connect time.</td><td>CI, dev containers, anything already injecting secrets.</td></tr><tr><td><code>{ &quot;kind&quot;: &quot;pgpass&quot; }</code></td><td>Matched out of <code>~/.pgpass</code> by host, port, database and user.</td><td>An existing PostgreSQL setup you do not want to duplicate.</td></tr><tr><td><code>{ &quot;kind&quot;: &quot;prompt&quot; }</code></td><td>Asked every time. Never persisted anywhere.</td><td>Break-glass production access.</td></tr></tbody></table><p>A PostgreSQL profile can also come from <code>pg_service.conf</code> — put the service name in the connection and the rest resolves from the file.</p><p>Exporting or sharing a profile rewrites every secret reference to <code>{ &quot;kind&quot;: &quot;prompt&quot; }</code>, so the exported copy cannot carry one out even by accident.</p><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to &quot;Environments&quot;">​</a></h2><p><code>dev</code>, <code>staging</code> and <code>prod</code> change behaviour, not just colour:</p><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">dev</th><th style="text-align:center;">staging</th><th style="text-align:center;">prod</th></tr></thead><tbody><tr><td>Coloured in the tree and status bar</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td></tr><tr><td>Destructive statement needs the connection name typed</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td></tr><tr><td>Destructive statement asks for a plain confirmation</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">(typed instead)</td></tr><tr><td>Recorded in query history</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td></tr><tr><td>An unclassifiable command is treated as destructive</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td></tr></tbody></table><p><code>pitta.query.confirmDestructive</code> decides which environments confirm; the typed confirmation on <code>prod</code> is not configurable away.</p><h2 id="read-only-connections" tabindex="-1">Read-only connections <a class="header-anchor" href="#read-only-connections" aria-label="Permalink to &quot;Read-only connections&quot;">​</a></h2><p>Tick <strong>Read-only</strong> on the profile and every write is refused — DML and DDL alike, in query mode and in the grid.</p><p>Where the engine has a real read-only session, Pitta sets it <em>and</em> enforces client-side. Where it does not, the badge says <strong>client-side only</strong>, because a guarantee the server is not making must never be presented as one. In that case the form recommends what actually enforces it: a read-only database user, or a Redis ACL.</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to &quot;TLS&quot;">​</a></h2><p>For any non-loopback host the form defaults to full verification (<code>verify-full</code> on PostgreSQL, and the equivalent on every other engine). Downgrading is possible and deliberate: it takes an explicit per-connection acknowledgement, and the connection is then badged <strong>insecure TLS</strong> everywhere it appears, for as long as it exists.</p><p>If your provider needs a CA bundle — Amazon RDS, Google Cloud SQL and Azure all do for full verification — point the <strong>CA certificate</strong> field at it. Each provider&#39;s file is named in <a href="/pitta-db/recipes/">the recipes</a>.</p><h2 id="ssh-tunnels" tabindex="-1">SSH tunnels <a class="header-anchor" href="#ssh-tunnels" aria-label="Permalink to &quot;SSH tunnels&quot;">​</a></h2><p>Every engine gets the same nine SSH fields, because they describe the bastion rather than the database: host, port, user, and one of ssh-agent, a private key with an optional passphrase, or a password. A jump host is supported.</p><p>Host keys are checked against <code>~/.ssh/known_hosts</code>. An unknown key prompts with its fingerprint and waits for you. It is never auto-accepted, and a key that does not match a known one stops the connection rather than warning about it.</p><div class="warning custom-block"><p class="custom-block-title">Topologies that discover their own nodes</p><p>A single forwarded port cannot serve addresses that only resolve on the far side of the bastion. So a tunnel is <strong>refused</strong>, with the reason, for Redis Cluster, Redis Sentinel, and a MongoDB SRV or seed-list connection that will be told about other hosts once it connects. Half-honouring the tunnel would connect to the seed and then quietly bypass it for every node after that.</p><p>Use a VPN, or a bastion-side proxy, for those. <a href="/pitta-db/recipes/ssh">More detail</a>.</p></div><h2 id="binding-a-file-to-a-connection" tabindex="-1">Binding a file to a connection <a class="header-anchor" href="#binding-a-file-to-a-connection" aria-label="Permalink to &quot;Binding a file to a connection&quot;">​</a></h2><p>The status bar shows which connection an open query file runs against. Click it to change, and the choice is remembered per file.</p><p>For a file that is committed and should always run somewhere specific, put a directive at the top instead — it travels with the file and beats the status-bar choice:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- @pitta connection: orders-staging</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- @pitta database: analytics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The directive is written in whichever comment syntax the file&#39;s language uses — <code>--</code>, <code>#</code>, or <code>//</code>.</p><p>A notebook binds as a whole rather than per cell, so cells in one notebook cannot silently run against different servers.</p><h2 id="connection-uris" tabindex="-1">Connection URIs <a class="header-anchor" href="#connection-uris" aria-label="Permalink to &quot;Connection URIs&quot;">​</a></h2><p>Paste a URI into the host field and it is parsed across the form. Each driver parses its own, so <code>postgres://</code>, <code>mysql://</code>, <code>mongodb+srv://</code> and <code>redis://</code> all work, including the query parameters that carry TLS options.</p><p>A password in a pasted URI is moved straight into the keychain and removed from the field. It does not survive in the profile.</p>`,36)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
